    name: 'Monastery Church of Our Lady — U Kajetánů',
    slug: 'u-kajetanu',
    localizedNames: { cz: 'Klášterní kostel Panny Marie — U Kajetánů', zh: '嘉耶当修道院圣母教堂' },
