    name: 'Vlasta Multifunctional Building',
    slug: 'multifunkcni-budova-vlasta-praha-10',
    localizedNames: { cz: 'Multifunkční budova Vlasta (Úřad městské části Praha 10)', zh: 'Vlasta多功能大楼（布拉格10区区政府）' },
    labels: ['municipal', 'communism'],
