    name: 'Homestead No. 11 (Hotel Baroko)',
    slug: 'usedlost-cp-11-malesice',
    localizedNames: { cz: 'Usedlost čp. 11 (dnes hotel Baroko)', zh: '11号庄园（巴洛克酒店）' },
    labels: ['homestead', 'cafe', 'baroque'],
    district: 'Praha 10',
