    name: 'Obelisk at Prague Castle',
    slug: 'obelisk-prague-castle',
    localizedNames: { cz: 'Obelisk na Pražském hradě (Vrcholek Žiži)', zh: '布拉格城堡方尖碑（日日丘遗址）' },
