    name: 'Statue of St. Adalbert (Charles Bridge)',
    slug: 'socha-sv-vojtecha-karluv-most',
    localizedNames: { cz: 'Socha svatého Vojtěcha (Karlův most)', zh: '圣沃伊切赫雕像（查理大桥）' },
