    name: 'Peruc',
    slug: 'peruc',
    localizedNames: { cz: 'Peruc', zh: '佩鲁茨' },
    labels: ['village-and-town', 'nature', 'medieval', 'outside'],
    coordinates: { lat: 50.34431978473373, lng: 13.962220515153717 },
