    name: 'Králův Dvůr',
    slug: 'kraluv-dvur',
    localizedNames: { cz: 'Králův Dvůr', zh: '国王庭院' },
    labels: ['castle and fortress', 'village-and-town', 'baroque', 'outside'],
    coordinates: { lat: 49.9470404782796, lng: 14.039324425293833 },
