    name: 'Zbraslav Chateau',
    slug: 'zbraslavsky-zamek',
    localizedNames: { cz: 'Zbraslavský zámek', zh: '兹布拉斯拉夫宫' },
    labels: ['palace', 'cultural', 'castle and fortress', 'baroque'],
