    name: 'Kozí Hrádek',
    slug: 'kozi-hradek',
    localizedNames: { cz: 'Kozí Hrádek', zh: '山羊堡' },
    labels: ['ruin', 'castle and fortress', 'medieval', 'outside'],
    coordinates: { lat: 49.389915862510584, lng: 14.723175583932957 },
