    name: 'Church of the Brethren Prayer Hall',
    slug: 'modlitebna-cirkve-bratrske-cernosice',
    localizedNames: { cz: 'Modlitebna Církve bratrské v Černošicích', zh: '切尔诺希采弟兄会祈祷堂' },
