    name: 'Praha-Podbaba Station',
    slug: 'nadrazi-praha-podbaba',
    localizedNames: { cz: 'Nádraží Praha-Podbaba', zh: '布拉格-波德巴巴火车站' },
    labels: ['transport'],
    district: 'Praha 6',
    quarter: 'Bubeneč',
    coordinates: { lat: 50.112392635952446, lng: 14.395342481244702 },
    rarity: 'common',
