    name: 'Na Staré poště Inn (Běchovice)',
    slug: 'hostinec-na-stare-poste-bechovice',
    localizedNames: { cz: 'Hostinec Na Staré poště (Běchovice)', zh: '别霍维采老驿站客栈' },
    labels: ['restaurants-and-cafes', 'cultural', 'classicism'],
    district: 'Praha 21',
