    name: 'Church of the Beheading of St. John the Baptist (Ořech)',
    slug: 'kostel-steti-sv-jana-krtitele-orech',
    localizedNames: { cz: 'Kostel Stětí sv. Jana Křtitele (Ořech)', zh: '施洗约翰斩首教堂（奥热赫）' },
    labels: ['church', 'baroque', 'outside'],
