    name: 'Chinese Pavilion at Cibulka',
    slug: 'cinsky-pavilon-cibulka',
    localizedNames: { cz: 'Čínský pavilon', zh: '齐布尔卡中国亭' },
    labels: ['park', 'classicism', 'hidden-gem'],
    district: 'Praha 5',
