    name: 'Trauttmansdorff Palace',
    slug: 'trauttmansdorffsky-palac',
    localizedNames: { cz: 'Trauttmansdorffský palác', zh: '特劳特曼斯多夫宫' },
    labels: ['palace', 'baroque'],
    district: 'Praha 1',
