    name: 'Chapel of the Holy Trinity (Sedlec)',
    slug: 'kaple-nejsvetejsi-trojice-sedlec',
    localizedNames: { cz: 'Kaple Nejsvětější Trojice (Sedlec)', zh: '圣三一小礼拜堂（塞德莱茨）' },
    labels: ['church', 'baroque'],
